#!/usr/bin/env bash
#
# configure.sh for cloner - modernized 2026
# Supports: Linux, macOS, FreeBSD, SunOS, Cygwin
# Native 64-bit by default. Optional 32-bit. Optional OpenSSL.
#

function makefile_main()
{
echo "#
# Code generated by configure
# 
# Warning! All changes made in this file will be lost!
#

default:
	@echo '-+- >> Available targets:'
	@echo '-+- = dynamic (preferred for most systems)'
	@echo '-+- = static'
	@echo '-+- = debug'

dynamic:
	@make -f Makefile.key
	@echo '-+- Making dynamic'
	@make -f Makefile.dynamic

static:
	@make -f Makefile.key
	@echo '-+- Making static'
	@make -f Makefile.static

debug:
	@make -f Makefile.key
	@echo '-+- Making debug'
	@make -f Makefile.debug

release:
	@make -f Makefile.key
	@echo '-+- Making release'
	@make -f Makefile.release

src:
	@echo '-+- Making src'
	@make -f Makefile.src
	
clean:
	@echo '-+- Making clean'
	@make -f Makefile.clean
" > Makefile
}

function makefile_key()
{
echo "#
# Code generated by configure
# 
# Warning! All changes made in this file will be lost!
#

CC = gcc
OUT = key

$TARGET:
	@echo '-+- Making key'
	@echo '-+- Compiling key.c'
	@\$(CC) key.c -o \$(OUT)
	@echo '-+- Generating key.h'
	@./key 
	@echo '-+- key.h ready' " > Makefile.$TARGET
}

function makefile_up()
{
# Build clean object list
OBJS="md5.o net.o irc.o cmds.o ident.o validate.o functions.o work.o work_fast.o"
if [ "$HAVE_SSL" = "true" ]; then
  OBJS="$OBJS ssl.o"
fi
OBJS="$OBJS main.o"

echo "#
# Code generated by configure
#
# Warning! All changes made in this file will be lost!
#

# The real target MUST be the first target in the file.

CC = gcc
OUT = $OUT
CFLAGS = $CFLAGS $FLAGS
LFLAGS = $LFLAGS

OBJS = $OBJS

$TARGET: key.h \$(OBJS)
	@echo '-+- Linking \$(OUT)'
	@\$(CC) \$(OBJS) -o \$(OUT) \$(CFLAGS) \$(LFLAGS)
	@echo '-+- Stripping debug information'
	@strip \$(OUT) || true
	@if [ -f validate.c ] && [ -f key.h ]; then \\
		echo '-+- Building validator'; \\
		\$(CC) md5.o -o validator validator.c $ARCHFLAGS || true; \\
		if [ -x ./validator ]; then echo '-+- Patching file'; ./validator \$(OUT) || true; fi; \\
	fi
	@mv \$(OUT) ../\$(OUT)
	@rm -fr ../cloner
	@ln -s \$(OUT) ../cloner
	@echo '-+- Done'

.SUFFIXES: .c .o

.c.o:
	@echo '-+- Compiling \$<'
	@\$(CC) -c \$< \$(CFLAGS)

# key.h is required by validate.c
validate.o: key.h

key.h:
	@make -f Makefile.key
"  > Makefile.$TARGET
}

function makefile_done()
{
	true
}

function makefile_release()
{
echo "	@echo '-+- Creating release'
	@mkdir cloner
	@mkdir cloner/vhost-examples	
	@echo -+- Stripping debug information
	@strip \$(OUT)
	@echo '-+- Building validator'
	@\$(CC) md5.o -o validator validator.c $ARCHFLAGS
	@echo '-+- Patching file'
	@./validator \$(OUT)
	@cp \$(OUT) cloner/\$(OUT)
	@ln -s \$(OUT) cloner/cloner
	@cp ../README  cloner/README
	@cp ../CHANGELOG cloner/CHANGELOG
	@cp ../vhost-examples/* cloner/vhost-examples	
	@tar -cf \$(OUT).tar cloner
	@rm -fr cloner
	@rm -fr \$(OUT)
	@gzip -9 -f \$(OUT).tar
	@mv \$(OUT).tar.gz ../\$(OUT).tar.gz" >> Makefile.$TARGET
}

function makefile_world()
{
	true
}

function makefile_deb()
{
echo "	@mv \$(OUT) ../\$(OUT)
	@rm -fr ../cloner 
	@ln -s \$(OUT) ../cloner" >> Makefile.$TARGET
}

function makefile_src()
{
    echo "#
# Code generated by configure
#
# Warning! All changes made in this file will be lost!
#    

OUT = cloner-\$VER-src

$TARGET:
	@echo '-+- Cleaning up'
	@rm -fr cloner
	@rm -fr *.o Makefile Makefile.* key.h key
	@echo '-+- Creating struct of files'
	@mkdir cloner
	@mkdir cloner/vhost-examples	
	@mkdir cloner/src
	@mkdir cloner/jococloner
	@cp ../vhost-examples/* cloner/vhost-examples/
	@cp configure cloner/src/configure
	@cp configure.sh cloner/src/configure.sh
	@cp *.h cloner/src/
	@cp *.c cloner/src/
	@cp ../jococloner/* cloner/jococloner/
	@cp ../CHANGELOG cloner/CHANGELOG
	@cp ../README cloner/README
	@echo '-+- Creating archive'
	@tar -cf \$(OUT).tar cloner/
	@rm -fr cloner
	@rm -fr \$(OUT)
	@gzip -9 -f \$(OUT).tar
	@mv \$(OUT).tar.gz ../\$(OUT).tar.gz" > Makefile.$TARGET    
}

function makefile_clean()
{
    echo "#
# Code generated by configure
#
# Warning! All changes made in this file will be lost!
#    

OUT = $OUT

$TARGET:
	@echo '-+- Cleaning up'
	@rm -fr cloner *.o validator key.h key Makefile Makefile.* *.log ../cloner ../\$(OUT)
	@rm -fr ../*.log " > Makefile.$TARGET		
    
}

function help()
{
	echo "-+-  --with-ipv6          enable IPv6 (default: on except Cygwin)"
	echo "-+-  --without-ipv6       disable IPv6"
	echo "-+-  --with-ssl           enable OpenSSL SSL/TLS support (default: auto-detect)"
	echo "-+-  --without-ssl        disable SSL/TLS"
	echo "-+-  --with-32bit         force 32-bit build (requires multilib)"
	echo "-+-  --without-validator  disable binary validation/protector"
	echo "-+-  --help               this help"
    exit 1
}

function getarg()
{
    IPSET=false
    VALIDSET=false
    SSLSET=false
    ARCHSET=false
    
    VALIDATOR=true
    HAVE_IPV6=true
    HAVE_SSL=auto
    FORCE_32BIT=false
    
    if [ "$UNAME" = "cygwin" ]; then
        HAVE_IPV6=false
    fi
    
    for arg in "$@"; do
        case "$arg" in
            --with-ipv6)
                if [ $IPSET = true ]; then echo "-+- Duplicated $arg"; exit 1; fi
                HAVE_IPV6=true; IPSET=true
                ;;
            --without-ipv6)
                if [ $IPSET = true ]; then echo "-+- Duplicated $arg"; exit 1; fi
                HAVE_IPV6=false; IPSET=true
                ;;
            --with-ssl)
                if [ $SSLSET = true ]; then echo "-+- Duplicated $arg"; exit 1; fi
                HAVE_SSL=true; SSLSET=true
                ;;
            --without-ssl)
                if [ $SSLSET = true ]; then echo "-+- Duplicated $arg"; exit 1; fi
                HAVE_SSL=false; SSLSET=true
                ;;
            --with-32bit)
                if [ $ARCHSET = true ]; then echo "-+- Duplicated $arg"; exit 1; fi
                FORCE_32BIT=true; ARCHSET=true
                ;;
            --without-validator)
                if [ $VALIDSET = true ]; then echo "-+- Duplicated $arg"; exit 1; fi
                VALIDATOR=false; VALIDSET=true
                ;;
            --help|-h)
                help
                ;;
            *)
                if [ -n "$arg" ]; then
                    echo "-+- Unknown option: $arg"
                    help
                fi
                ;;
        esac
    done
}

function detect_openssl()
{
    SSL_CFLAGS=""
    SSL_LIBS=""
    if [ "$HAVE_SSL" = "false" ]; then
        return
    fi
    
    if command -v pkg-config >/dev/null 2>&1; then
        if pkg-config --exists openssl 2>/dev/null; then
            SSL_CFLAGS=$(pkg-config --cflags openssl)
            SSL_LIBS=$(pkg-config --libs openssl)
            HAVE_SSL=true
            return
        fi
    fi
    
    for prefix in /usr /usr/local /opt/homebrew /opt/local; do
        if [ -f "$prefix/include/openssl/ssl.h" ]; then
            SSL_CFLAGS="-I$prefix/include"
            SSL_LIBS="-L$prefix/lib -lssl -lcrypto"
            if [ -d "/opt/homebrew/opt/openssl" ]; then
                SSL_CFLAGS="-I/opt/homebrew/opt/openssl/include"
                SSL_LIBS="-L/opt/homebrew/opt/openssl/lib -lssl -lcrypto"
            elif [ -d "/usr/local/opt/openssl" ]; then
                SSL_CFLAGS="-I/usr/local/opt/openssl/include"
                SSL_LIBS="-L/usr/local/opt/openssl/lib -lssl -lcrypto"
            fi
            HAVE_SSL=true
            return
        fi
    done
    
    if [ "$HAVE_SSL" = "true" ]; then
        echo "-+- ERROR: --with-ssl requested but OpenSSL not found"
        exit 1
    fi
    HAVE_SSL=false
}

function make_echo()
{
    echo "-+- Generating Makefile.$TARGET"    
}

function make_me()
{
    makefile_up
}

function do_dynamic()
{
    make_echo
    FLAGS=""
    make_me
}

function do_static()
{
    make_echo
    FLAGS="-static"
    make_me
}

function do_debug()
{
    make_echo
    FLAGS="-DDEBUG"
    CFLAGS="$CFLAGS -Wall -ggdb"
    makefile_up
    makefile_deb
}

function do_release()
{
    FLAGS="-static"
    makefile_up
    makefile_release
}

# ========== main ==========

UNAME=`uname | awk '{ print tolower($1) }'`

case $UNAME in
    sunos) UNAME="sunos";;
    cygwin*) UNAME="cygwin";;
    darwin) UNAME="darwin";;
    freebsd) UNAME="freebsd";;
esac

MACHINE=`uname -m`

VER=`grep CLONER_VERSION_STR defines.h | awk '{ print substr($3, 2, length($3)-2) }'`
VER=`echo $VER | tr -d '\r'`
OUT="cloner-$VER-$UNAME"
GCC=`gcc -dumpversion 2>/dev/null || echo "unknown"`

ARCHFLAGS=""
CFLAGS="-pipe -O2 -Wall"
LFLAGS=""

getarg "$@"

if [ "$FORCE_32BIT" = "true" ]; then
    ARCHFLAGS="-m32"
    CFLAGS="$CFLAGS -m32"
    echo "-+- Forcing 32-bit build"
else
    echo "-+- Building native architecture ($MACHINE)"
fi

if [ "$UNAME" = "sunos" ]; then 
    LFLAGS="-lsocket -lnsl"
    CFLAGS="$CFLAGS -DSUNOS"
elif [ "$UNAME" = "cygwin" ]; then 
    CFLAGS="$CFLAGS -DWINDOWS"
elif [ "$UNAME" = "darwin" ]; then
    CFLAGS="$CFLAGS -D_DARWIN_C_SOURCE"
elif [ "$UNAME" = "freebsd" ]; then
    CFLAGS="$CFLAGS -D_FREEBSD"
fi

detect_openssl

if [ "$HAVE_IPV6" = "true" ]; then
    CFLAGS="$CFLAGS -DHAVE_IPV6"
fi

if [ "$VALIDATOR" = "true" ]; then
    CFLAGS="$CFLAGS -DHAVE_VALIDATOR"
fi

if [ "$HAVE_SSL" = "true" ]; then
    CFLAGS="$CFLAGS -DHAVE_SSL $SSL_CFLAGS"
    LFLAGS="$LFLAGS $SSL_LIBS"
fi

echo "-+- Running configure"
echo "-+- Operating system: $UNAME"
echo "-+- Architecture: $MACHINE"
echo "-+- Gnu C Compiler: $GCC"
echo -n "-+- IPv6: "
if [ "$HAVE_IPV6" = "true" ]; then echo "yes"; else echo "no"; fi
echo -n "-+- SSL/TLS (OpenSSL): "
if [ "$HAVE_SSL" = "true" ]; then echo "yes"; else echo "no (use --with-ssl to force)"; fi
echo -n "-+- Validator: "
if [ "$VALIDATOR" = "true" ]; then echo "yes"; else echo "no"; fi
echo "-+- CFLAGS: $CFLAGS"
echo "-+- LFLAGS: $LFLAGS"
echo "-+- Generating Makefiles"

makefile_main
for i in key dynamic static debug release src clean
do
    TARGET="$i"    
    case $TARGET in
	key) makefile_key ;;
	dynamic) do_dynamic ;;
	static) do_static ;;
	debug) do_debug ;;
	release) do_release ;;
	src) makefile_src ;;
	clean) makefile_clean ;;
    esac 
    makefile_done
done
echo '-+- Configure is done'
